fn component_kind(component: Component, motion: bool) -> Kind {
    match (component.is_translation(), motion) {
        (true, true) => Kind::Translation,
        (false, true) => Kind::Rotation,
        (true, false) => Kind::Force,
        (false, false) => Kind::Moment,
    }
}

